head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30409";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30409.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_register_onclick
 * @description 「동의」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30409.btn_register_onclick' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_list_onclick = async function(e){
    try {
        await scwin.list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30409.btn_list_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_list
 * @description list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_list = async function () {
    const sbmOptions = {
        id: "tx_fn_list",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_listReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/issue/IRroom.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'irCenter') {
        $c.util.getComponent('dma_listReq').set('method', 'searchIRroomResv');
    } else {
        if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'mainMeetroom') {
            $c.util.getComponent('dma_listReq').set('method', 'searchMainMeetingroomResv');
        } else {
            if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'smartBzCenter') {
                $c.util.getComponent('dma_listReq').set('method', 'searchSmartBzCenterResv');
            } else {
                $c.util.getComponent('dma_listReq').set('method', "");
                await $c.win.alert('Market Square 목록 오류발생. 관리자에게 문의하세요.');
                return;
            }
        }
    }
    const nr = await scwin.tx_fn_list();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30401/jldfil30401.xml", { "method": 'searchIRroomResv' });
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if ($("#ipt_perInfoChk").is(":checked") !== true) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해야 신청가능합니다.");
        $c.util.getComponent("ipt_perInfoChk").focus();
        return;
    }
    if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'irCenter') {
        $c.util.getComponent('dma_listReq').set('method', 'goIRroomResv');
    } else {
        if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'mainMeetroom') {
            $c.util.getComponent('dma_listReq').set('method', 'goMainMeetingroomResv');
        } else {
            if ($c.util.getComponent('dma_listReq').get('confroomGubun') === 'smartBzCenter') {
                $c.util.getComponent('dma_listReq').set('method', "goSmartBzCenterResv");
            } else {
                $c.util.getComponent('dma_listReq').set('method', "");
                await $c.win.alert('Market Square 동의 오류발생. 관리자에게 문의하세요.');
                return;
            }
        }
    }
    const nr = await scwin.tx_fn_register();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30402/jldfil30402.xml", { "method": 'goIRroomResv' });
    }
};
